import React, { forwardRef } from 'react';

import { chipKeyCSS } from './ChipKey.sty.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

//#region Typings
/** Accepted properties for the Key. */
export type ChipKeyProps = WithChildren & StylingProps & DataTestId;
//#endregion

/** Component used for adding elements to the key slot. */
export const ChipKey = /* @__PURE__ */ forwardRef<HTMLDivElement, ChipKeyProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
    }: ChipKeyProps = props;

    return (
      <Flex
        alignSelf="stretch"
        alignItems="center"
        minWidth={0}
        ref={forwardedRef}
        data-testid={dataTestId}
        gap={2}
        className={consumerClassName}
        style={consumerStyle}
      >
        <div className={chipKeyCSS}>{children}</div>
      </Flex>
    );
  },
);

(ChipKey as typeof ChipKey & { displayName: string }).displayName = 'Chip.Key';
